import {activeSeconds,togglePause,acceptPosition,metTarget} from './fitness.js';
import {uid,starterRoutines,demoRecords,demoProfile,foods,baseMeals} from './data.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>structuredClone(v),dateKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const state={demo:false,route:'today',user:null,profile:null,records:[],draft:null,stats:{streak:0,total:0,days:[],today:false},friends:[],photos:[],sync:'Salvo',dirty:false,ai:null};
const navs=[['today','◈','Hoje'],['workouts','▥','Treinos'],['food','◷','Alimentação'],['progress','↗','Evolução'],['taf','◎','TAF'],['running','➜','Corrida'],['music','♫','Música'],['friends','♧','Amigos'],['ai','✦','Auxiliar']];
const items=k=>state.records.filter(r=>r.kind===k);
let saveTimer,toastTimer,savePromise=null;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',5000)}
async function api(path,method='GET',body){let r;try{r=await fetch('/api/'+path,{method,headers:body instanceof Blob?{'Content-Type':body.type}:body?{'Content-Type':'application/json'}:{},body:body===undefined?undefined:body instanceof Blob?body:JSON.stringify(body),credentials:'same-origin'})}catch{throw new Error('Sem conexão. Seu treino continua no rascunho deste aparelho.')}let v;try{v=await r.json()}catch{throw new Error('Resposta inesperada do servidor.')}if(!r.ok){const e=new Error(v.error||'Não foi possível concluir.');e.status=r.status;throw e}return v}
function demoPersist(){localStorage.setItem('forma-demo',JSON.stringify({profile:state.profile,records:state.records,draft:state.draft}));demoStats()}
function demoStats(){const days=[...new Set(items('workout').filter(r=>qualifies(r.data)).map(r=>dateKey(new Date(r.data.finished_at))))];const today=dateKey();let d=new Date(today+'T12:00:00-03:00'),streak=0;if(!days.includes(today))d.setDate(d.getDate()-1);while(days.includes(dateKey(d))){streak++;d.setDate(d.getDate()-1)}state.stats={days,total:days.length,streak,today:days.includes(today)}}
function qualifies(d){return new Set((d.exercises||[]).filter(e=>e.sets.length&&e.sets.every(s=>s.done&&s.reps>0)).map(e=>e.id)).size>=3}
function completed(d){return d?.exercises?.filter(e=>e.sets.length&&e.sets.every(s=>s.done&&s.reps>0)).length||0}
async function put(kind,data,id=uid(),version){const old=state.records.find(r=>r.id===id);let row;if(state.demo){row={id,kind,data:clone(data),version:(old?.version||0)+1};if(kind==='workout')row.data.finished_at=old?.data.finished_at||new Date().toISOString()}else row=await api('records','POST',{id,kind,data,version:version??old?.version});state.records=state.records.filter(r=>r.id!==id).concat(row);if(state.demo)demoPersist();return row}
async function remove(id){if(!state.demo)await api('records/'+id,'DELETE');state.records=state.records.filter(r=>r.id!==id);if(state.demo)demoPersist()}
function cacheDraft(){if(state.draft&&!state.demo)localStorage.setItem('forma-draft-'+state.user.id,JSON.stringify({draft:state.draft,dirty:state.dirty}));if(state.demo)demoPersist()}
function changed(){state.dirty=true;state.sync=state.demo?'Salvo na demonstração':'Rascunho salvo neste aparelho';cacheDraft();syncLabel();clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveDraft().catch(e=>{state.sync=e.message;syncLabel()}),800)}
async function saveDraft(){if(!state.draft||!state.dirty)return;if(savePromise){await savePromise;if(state.dirty)return saveDraft();return}const snapshot=clone(state.draft),snapshotText=JSON.stringify(state.draft.data);state.sync=state.demo?'Salvo na demonstração':'Sincronizando…';syncLabel();savePromise=(async()=>{try{const row=await put('draft',snapshot.data,snapshot.id,snapshot.version);if(state.draft?.id===snapshot.id){state.draft.version=row.version;state.dirty=JSON.stringify(state.draft.data)!==snapshotText;state.sync=state.dirty?'Alterações pendentes':state.demo?'Salvo na demonstração':'Salvo na nuvem';cacheDraft();syncLabel()}}catch(e){state.sync=e.status===409?'Conflito: recarregue e escolha a versão do treino.':'Pendente: '+e.message;syncLabel();throw e}finally{savePromise=null}})();await savePromise}
function syncLabel(){for(const el of document.querySelectorAll('[data-sync]'))el.textContent=state.sync}
async function load(){const s=await api('session');state.user=s.user;state.profile=s.profile;if(!state.profile)throw new Error('Perfil não encontrado. Confira a instalação do banco.');const [records,stats,friends]=await Promise.all([api('records'),api('stats'),api('friends')]);state.records=records;restoreRun();state.ai=items('ai_proposal')[0]?.data||null;state.stats=stats;state.friends=friends;state.draft=items('draft')[0]||null;const cached=JSON.parse(localStorage.getItem('forma-draft-'+state.user.id)||'null');if(cached?.dirty){if(!state.draft||cached.draft.version===state.draft.version){state.draft=cached.draft;state.dirty=true;state.sync='Rascunho local pendente';}else{state.sync='Usando versão atual da nuvem';toast('O treino mudou em outro dispositivo. A versão da nuvem foi carregada. O rascunho local pode ser recuperado no treino.');}}else{state.sync='Salvo na nuvem';state.dirty=false}render()}
function enterDemo(){state.demo=true;const saved=JSON.parse(localStorage.getItem('forma-demo')||'null');state.user={id:'demo',email:'demo@exemplo.local'};state.profile=saved?.profile||clone(demoProfile);state.records=saved?.records||demoRecords();state.draft=saved?.draft||null;state.friends=[];restoreRun();state.ai=items('ai_proposal')[0]?.data||null;demoStats();render()}
const button=(label,action,classes='',attrs='')=>`<button type="button" class="${classes}" data-action="${action}" ${attrs}>${label}</button>`;
function openModal(title,content){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('✕','close','ghost','aria-label="Fechar"')}</div>${content}`;if(!modal.open)modal.showModal();modal.querySelector('input,textarea,select,button')?.focus()}
function formModal(title,html,handler,submit='Salvar'){openModal(title,`<form id="modal-form" class="form">${html}<p class="error" data-error></p><div class="actions"><button type="submit" class="primary">${submit}</button>${button('Cancelar','close','ghost')}</div></form>`);modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;f.querySelector('[data-error]').textContent='';try{await handler(Object.fromEntries(new FormData(f)),f);modal.close();render()}catch(err){f.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false}}}
const field=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<span class="input-wrap"><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${type==='password'?button('Mostrar','toggle-password','ghost','aria-label="Mostrar senha" aria-pressed="false"'):''}</span></label>`;
const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
function auth(mode='login',message=''){state.user=null;app.innerHTML=`<div class="auth"><section class="auth-art"><div class="brand"><img src="/icon.svg" alt="">forma</div><h1>Seu ritmo.<br>Sua força.<br><span class="accent">Sua evolução.</span></h1><p>Treino, alimentação e progresso. Um espaço para cuidar da sua rotina, uma série de cada vez.</p><div class="chips"><span class="chip">Treino ABC</span><span class="chip">Alimentação possível</span><span class="chip">Progresso com amigos</span></div></section><section class="auth-main"><div class="brand"><img src="/icon.svg" alt="">forma</div><h2>${mode==='signup'?'Crie seu espaço':mode==='recover'?'Recupere sua conta':'Bom ter você aqui'}</h2><p class="muted">${mode==='login'?'Entre para continuar de onde parou.':'Seus dados de saúde ficam privados.'}</p><div class="tabs">${button('Entrar','auth-login',mode==='login'?'active':'')}${button('Criar conta','auth-signup',mode==='signup'?'active':'')}</div><form id="auth-form" class="form">${mode==='signup'?field('name','Seu nome','','text','required maxlength="80"')+field('username','Nome de usuário','','text','required pattern="[a-z0-9_]{3,24}" placeholder="ex.: walyson_caio" autocomplete="username"'):''}${field('email','E-mail','','email','required autocomplete="email"')}${mode!=='recover'?field('password','Senha','','password',`required ${mode==='signup'?'minlength="10"':''} autocomplete="${mode==='signup'?'new-password':'current-password'}"`):''}<p class="error" data-error>${esc(message)}</p><button class="primary" type="submit">${mode==='signup'?'Criar conta':mode==='recover'?'Enviar link':'Entrar'}</button></form><div class="actions" style="margin-top:16px">${button('Esqueci minha senha','auth-recover','ghost')}${button('Explorar demonstração','demo','ghost')}</div><p class="subtle">A demonstração usa dados locais e não cria uma conta.</p></section></div>`;app.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{const v=Object.fromEntries(new FormData(f));if(mode==='recover'){await api('recover','POST',v);auth('login','Se esse e-mail estiver cadastrado, você receberá um link.')}else{const r=await api(mode==='signup'?'signup':'login','POST',v);if(r.confirmation)auth('login','Conta criada. Confirme seu e-mail antes de entrar.');else{state.demo=false;await load()}}}catch(err){f.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false}}}
function render(){if(!state.user){auth();return}const p=state.profile;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt="">forma</div><nav class="nav" aria-label="Principal">${navs.map(([r,s,l])=>button(`<span class="symbol">${s}</span>${l}`,'nav',state.route===r?'active':'',`data-route="${r}"`)).join('')}</nav><div class="side-bottom"><span class="pill">${state.stats.streak} dias de ofensiva</span><div class="userline"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><br><small>@${esc(p.username)}</small></div></div>${button('Meu perfil','profile','ghost')}${button('Sair','logout','ghost')}</div></aside><main class="main"><header class="topbar"><div class="brand mobile-brand"><img src="/icon.svg" alt="">forma</div><div class="greeting"><p>Olá, <strong>${esc(p.name.split(' ')[0])}</strong></p><small>${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</small></div><div class="top-actions"><span class="pill">♨ ${state.stats.streak} dias</span>${button('Perfil','profile','ghost')}</div></header>${state.demo?'<div class="demo-banner">Demonstração • dados salvos apenas neste navegador. Login, amizades, fotos e Gemini precisam da configuração dos serviços.</div>':''}<div id="view">${views[state.route]()}</div></main></div>`;bindView();updateTimes();updateRunMetrics();mountMusic()}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="actions">${actions}</div></div>`}
function week(){const now=new Date(),day=(now.getDay()+6)%7;now.setDate(now.getDate()-day);return `<div class="week">${['S','T','Q','Q','S','S','D'].map((l,i)=>{const d=new Date(now);d.setDate(d.getDate()+i);const k=dateKey(d);return `<div class="day ${state.stats.days.includes(k)?'done':''} ${k===dateKey()?'today':''}">${l}<strong>${state.stats.days.includes(k)?'✓':d.getDate()}</strong></div>`}).join('')}</div>`}
function today(){const routines=items('routine'),index=(new Date().getDay()+6)%7,r=routines.find(r=>r.data.group===['A','B','C','A','B','C',''][index])||routines[0];return head('Um passo mais forte.','Sua rotina de hoje, sem complicação.')+planNotice()+dailyTaf()+`<div class="grid two"><section class="panel focus"><span class="eyebrow">${state.draft?'Treino em andamento':index===6?'Domingo • recuperação':'Sua próxima sessão'}</span><span class="huge">${esc(state.draft?.data.group||r?.data.group||'F')}</span><h2>${esc(state.draft?.data.name||r?.data.name||'Monte seu primeiro treino')}</h2><p class="muted">${state.draft?`${completed(state.draft.data)} exercícios concluídos. Retome do ponto em que parou.`:index===6?'Descanso também faz parte da evolução. Treine conforme seu planejamento e recuperação.':r?`${r.data.exercises.length} exercícios · cargas e repetições no seu ritmo.`:'Cadastre uma ficha ou peça uma proposta ao auxiliar.'}</p>${button(state.draft?'Continuar treino':r?'Iniciar treino':'Criar treino',state.draft?'continue':r?'start':'new-routine','primary',r?`data-id="${r.id}"`:'')}</section><section class="panel"><span class="eyebrow">Sua constância</span><div class="metric">${state.stats.streak}<span> dias de ofensiva</span></div><p class="muted">${state.stats.today?'Ofensiva de hoje concluída. Bom trabalho!':'Conclua todas as séries de pelo menos 3 exercícios e finalize o treino.'}</p>${week()}<p class="subtle">Dias consecutivos de calendário. Respeite os dias de descanso, mesmo que a sequência reinicie.</p></section></div><div class="grid three" style="margin-top:20px"><div class="panel"><small>Peso mais recente</small><div class="metric">${esc(latestWeight()||'—')}<span> kg</span></div><small>Meta informada: ${esc(state.profile.settings?.target||'—')} kg</small></div><div class="panel"><small>Dias treinados</small><div class="metric">${state.stats.total}<span> dias</span></div><small>Uma contagem por dia válido</small></div><div class="panel"><small>Seu foco</small><h3 style="margin:17px 0">${esc(state.profile.settings?.goal||'Defina seu objetivo')}</h3>${button('Ajustar perfil','profile','ghost')}</div></div><div class="section-title"><h2>Alimentação no seu horário</h2>${button('Ver refeições','nav','ghost','data-route="food"')}</div><section class="panel">${items('meal').sort((a,b)=>(a.data.time||'').localeCompare(b.data.time||'')).map(r=>`<div class="row"><div><span class="meal-time">${esc(r.data.time)}</span></div><div style="flex:1"><h3>${esc(r.data.name)}</h3><p class="muted">${esc(r.data.content)}</p></div></div>`).join('')||'<p class="empty">Cadastre suas refeições para acompanhar aqui.</p>'}</section>`}
function latestWeight(){return items('measurement').sort((a,b)=>b.data.date.localeCompare(a.data.date))[0]?.data.weight}
function workouts(){if(state.draft)return liveWorkout();return planNotice()+head('Seu treino. Seu ritmo.','Fichas que você pode ajustar e acompanhar.',button('Criar ficha','new-routine','primary')+button('Auxiliar IA','nav','ghost','data-route="ai"'))+`<div class="grid three">${items('routine').map(r=>`<section class="panel"><div class="card-top"><span class="letter">${esc(r.data.group||'•')}</span><div><h3>${esc(r.data.name)}</h3><small>${r.data.exercises.length} exercícios</small></div></div>${r.data.exercises.slice(0,4).map(e=>`<p class="muted">${esc(e.name)} <small>· ${e.sets.length} séries</small></p>`).join('')}${r.data.exercises.length>4?`<small>+ ${r.data.exercises.length-4} exercícios</small>`:''}<div class="card-footer">${button('Iniciar','start','primary',`data-id="${r.id}"`)}${button('Editar','edit-routine','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></section>`).join('')}</div>${!items('routine').length?`<section class="panel empty"><p>Seu espaço de treino está pronto para receber as primeiras fichas.</p>${button('Adicionar fichas ABC de exemplo','seed-routines','primary')}<p class="subtle">Exemplos educativos. Ajuste com seu professor.</p></section>`:''}<div class="section-title"><h2>Histórico de sessões</h2></div><section class="panel">${items('workout').sort((a,b)=>new Date(b.data.finished_at)-new Date(a.data.finished_at)).map(r=>`<div class="row"><div><h3>${esc(r.data.name)}</h3><small>${new Date(r.data.finished_at).toLocaleString('pt-BR')} · ${completed(r.data)} exercícios concluídos · ${qualifies(r.data)?'dia válido':'sessão parcial'}</small></div><div class="actions">${button('Revisar','review-workout','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></div>`).join('')||'<p class="empty">Suas sessões aparecerão aqui depois de finalizar.</p>'}</section>`}
function liveWorkout(){const d=state.draft.data,total=d.exercises.reduce((n,e)=>n+e.sets.length,0),done=d.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0);return head(esc(d.name),'Registre cada série e avance com controle.',button('Editar sessão','edit-session','ghost'))+`<div class="workbar"><div><small>Tempo de treino</small><div class="time" data-elapsed>00:00</div></div><div><small>Descanso</small><div class="time" data-rest>—</div></div>${button(d.paused_at?'Retomar':'Pausar','pause-workout','primary')}${d.paused_at?'<span class="pill">Pausado</span>':''}${button('Descansar 90 s','rest','ghost',d.paused_at?'disabled':'')}${button('Pular descanso','skip-rest','ghost')}${button('Finalizar','finish','primary')}</div><small data-sync>${esc(state.sync)}</small><div class="progress"><div style="width:${total?done/total*100:0}%"></div></div><p class="muted">${done}/${total} séries · ${completed(d)}/3 exercícios para a ofensiva do dia</p>${!state.demo&&localStorage.getItem('forma-draft-'+state.user.id)?button('Resolver rascunho local','recover-draft','ghost'):''}${d.exercises.map((e,i)=>`<section class="panel exercise"><div class="card-top"><span class="letter">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><small>${e.sets.length} séries · descanso ${esc(e.rest||90)} s ${e.name==='Prancha'?'· reps = segundos':''}</small></div></div><details><summary>Como executar e para que serve</summary><p>${esc(e.purpose||'Descrição ainda não cadastrada.')}</p><p>${esc(e.execution||'Peça orientação ao seu professor.')}</p><p class="muted">Alternativa: ${esc(e.alternative||'Consulte seu professor.')}</p>${button('Ouvir explicação','speak-ex','ghost',`data-ex="${i}"`)}</details><div class="set-head"><span>Série</span><span>Carga (kg)</span><span>${e.name==='Prancha'?'Segundos':'Reps'}</span><span>Feita</span></div>${e.sets.map((s,j)=>`<div class="set-row ${s.done?'done':''}"><span>${j+1}</span><input type="number" min="0" max="1000" step="0.5" value="${s.kg}" aria-label="Carga da série ${j+1} de ${esc(e.name)}" ${d.paused_at?'disabled':''} data-live="kg" data-ex="${i}" data-set="${j}"><input type="number" min="1" max="200" value="${s.reps}" aria-label="Repetições da série ${j+1} de ${esc(e.name)}" ${d.paused_at?'disabled':''} data-live="reps" data-ex="${i}" data-set="${j}">${button(s.done?'✓':'○','set-done',s.done?'primary':'ghost',`${d.paused_at?'disabled':''} data-ex="${i}" data-set="${j}" aria-label="${s.done?'Desmarcar':'Concluir'} série ${j+1}" aria-pressed="${s.done}"`)}</div>`).join('')}</section>`).join('')}<div class="actions">${button('Salvar e sair do treino','leave-session','ghost')}${button('Descartar sessão','discard-session','danger ghost')}</div>`}
function food(){return head('Alimentação possível.','Seu cardápio a partir do que você tem e pode comprar.',button('Nova refeição','new-meal','primary'))+`<div class="grid two"><section class="grid">${items('meal').sort((a,b)=>(a.data.time||'').localeCompare(b.data.time||'')).map(r=>`<article class="panel"><div class="card-top"><span class="meal-time">${esc(r.data.time)}</span><h3>${esc(r.data.name)}</h3></div><p>${esc(r.data.content)}</p><p class="muted">${esc(r.data.purpose)}</p><div class="actions">${button('Editar','edit-meal','ghost',`data-id="${r.id}"`)}${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</div></article>`).join('')||`<div class="panel empty"><p>Cadastre seu plano alimentar ou peça uma sugestão ao auxiliar.</p>${button('Adicionar horários de exemplo','seed-meals','ghost')}</div>`}</section><aside><div class="panel"><div class="section-title" style="margin-top:0"><h2>Minha despensa</h2>${button('+','new-pantry','primary','aria-label="Adicionar alimento"')}</div><p class="muted">O auxiliar consulta os alimentos que você tem ou pode comprar.</p>${items('pantry').map(r=>`<div class="row"><div><h3>${esc(r.data.name)}</h3><small>${r.data.available?'Tenho em casa':'Posso comprar'} · ${esc(r.data.quantity)} ${esc(r.data.unit)} ${Number(r.data.price)>0?'· R$ '+Number(r.data.price).toFixed(2):''}</small></div><div class="actions">${button('Editar','edit-pantry','ghost',`data-id="${r.id}"`)}${button('✕','delete-record','ghost danger',`data-id="${r.id}" aria-label="Excluir ${esc(r.data.name)}"`)}</div></div>`).join('')||'<p class="empty">Adicione seus alimentos disponíveis.</p>'}</div><div class="notice">As sugestões da IA precisam de revisão. Porções devem indicar peso cru ou cozido. Não tratamos substituições como nutricionalmente idênticas.</div></aside></div>`}
function progress(){const rows=items('measurement').sort((a,b)=>a.data.date.localeCompare(b.data.date));return head('Evolução que você acompanha.','Compare medidas, desempenho e fotos no seu ritmo.',button('Registrar medidas','new-measurement','primary'))+`<div class="grid two"><section class="panel"><h2>Peso ao longo do tempo</h2><p class="muted">Meta informada: ${esc(state.profile.settings?.target||'—')} kg. O peso sozinho não distingue músculo de gordura.</p><div class="chart">${rows.slice(-10).map(r=>`<div class="bar" style="height:${Math.min(100,Number(r.data.weight)/Math.max(...rows.map(x=>Number(x.data.weight)))*100)}%" title="${esc(r.data.date)}: ${esc(r.data.weight)} kg"><small>${esc(r.data.weight)}</small></div>`).join('')||'<p class="empty">Registre sua primeira medida.</p>'}</div><small>Últimos ${Math.min(rows.length,10)} registros · ordem cronológica · barras a partir de zero</small></section><section class="panel"><h2>Constância</h2><div class="metric">${state.stats.total}<span> dias treinados</span></div>${week()}<p class="subtle">Um dia só conta após finalizar pelo menos 3 exercícios completos.</p></section></div><div class="section-title"><h2>Medidas corporais</h2></div><section class="panel table-wrap"><table><thead><tr><th>Data</th><th>Peso</th><th>Cintura</th><th>Coxa</th><th>Braço</th><th>Ações</th></tr></thead><tbody>${rows.reverse().map(r=>`<tr><td>${esc(r.data.date)}</td><td>${esc(r.data.weight)} kg</td><td>${esc(r.data.waist||'—')} cm</td><td>${esc(r.data.thigh||'—')} cm</td><td>${esc(r.data.arm||'—')} cm</td><td>${button('Editar','edit-measurement','ghost',`data-id="${r.id}"`)} ${button('Excluir','delete-record','ghost danger',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></section><div class="section-title"><h2>Fotos privadas</h2><div class="actions">${button('Atualizar','load-photos','ghost')}${button('Enviar foto','upload-photo','primary')}</div></div><p class="muted">Só você pode acessar. Fotos não são compartilhadas com amigos nem enviadas à IA automaticamente.</p><div class="photos">${state.photos.map(p=>`<article class="panel"><img src="${esc(p.url)}" alt="${esc(p.caption||'Registro de evolução')}" loading="lazy"><p>${esc(p.caption)}</p><small>${new Date(p.created_at).toLocaleDateString('pt-BR')}</small><div class="card-footer">${button('Legenda','edit-photo','ghost',`data-id="${p.id}"`)}${button('Excluir','delete-photo','ghost danger',`data-id="${p.id}"`)}</div></article>`).join('')||'<div class="panel empty">Carregue ou envie suas fotos.</div>'}</div>`}
function friends(){return head('Evoluir em boa companhia.','Encontre amigos pelo nome de usuário e compartilhe sua constância.',button('Atualizar','refresh-friends','ghost'))+`<div class="grid two"><section class="panel"><h2>Seu círculo</h2>${state.friends.map(f=>`<div class="row"><div class="userline"><span class="avatar">${esc(f.name?.slice(0,1).toUpperCase())}</span><div><h3>${esc(f.name)}</h3><small>@${esc(f.username)}</small><p class="muted">${f.status==='pending'?(f.incoming?'Convite recebido':'Convite enviado'):f.progress?`♨ ${f.progress.streak} dias de ofensiva · ${f.progress.total} dias treinados ${f.progress.today?'· treinou hoje':''}`:'Progresso privado'}</p></div></div><div class="actions">${f.status==='pending'&&f.incoming?button('Aceitar','accept-friend','primary',`data-id="${f.id}"`):''}${button(f.status==='accepted'?'Remover':'Cancelar','delete-friend','ghost danger',`data-id="${f.id}"`)}</div></div>`).join('')||'<p class="empty">Seu círculo começa com um convite. Busque sua esposa ou seus amigos pelo @usuário.</p>'}</section><section class="panel"><h2>Encontrar pessoas</h2><form id="people-form" class="form">${field('q','Nome de usuário','','text','required minlength="2" placeholder="ex.: walyson"')}<button type="submit" class="primary">Buscar</button></form><div id="people-results"></div><div class="notice">Seu nome e @usuário aparecem na busca. Amigos aceitos só veem sua ofensiva e total de dias se você ativar o compartilhamento no perfil.</div><label class="check"><input type="checkbox" id="share-progress" ${state.profile.share_progress?'checked':''}>Compartilhar meu progresso com amigos</label></section></div>`}
function ai(){return head('Seu auxiliar, com contexto.','Treino e alimentação com base na sua rotina.')+`<div class="grid two"><section class="panel"><div class="ai-mark"><span class="avatar">✦</span><div><h2 style="margin:0">Auxiliar Forma</h2><small>Gemini · sugestões para você revisar</small></div></div><form id="ai-form" class="form"><label>O que vamos organizar?<select name="mode"><option value="chat">Conversar e tirar dúvidas</option><option value="training_plan">Propor treino ABC completo</option><option value="routine">Propor uma ficha de treino</option><option value="meal_plan">Propor alimentação do dia</option><option value="meal">Propor uma refeição</option></select></label>${area('prompt','Sua mensagem','')}<div class="actions">${button('🎙 Ditar mensagem','dictate','ghost')}${button('Entender meu perfil','assess','ghost')}</div><label class="check"><input type="checkbox" name="consent" required>Autorizo enviar meu perfil, fichas, medidas e despensa ao Gemini para este pedido.</label><label>Foto para comparar (opcional)<select name="photo_id"><option value="">Nenhuma foto</option>${state.photos.map(p=>`<option value="${p.id}">${esc(p.caption||new Date(p.created_at).toLocaleDateString('pt-BR'))}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="photo_consent">Também autorizo enviar a foto escolhida ao Gemini.</label><p class="error" data-error></p><button type="submit" class="primary">Enviar ao auxiliar</button></form><p class="subtle">Ditado e leitura usam recursos de voz do navegador, quando disponíveis. A IA não identifica biotipo como diagnóstico.</p></section><section class="panel"><h2>Sua resposta</h2>${state.ai?`<div class="chat">${esc(state.ai.answer)}</div><div class="actions" style="margin-top:20px">${button('Ouvir resposta','speak-ai','ghost')}${button('Parar áudio','stop-audio','ghost')}${state.ai.proposal?button('Revisar proposta','apply-ai','primary'):''}</div>`:'<p class="empty">Descreva seu objetivo ou peça uma alternativa para um exercício. O auxiliar consultará os dados que você autorizar.</p>'}<div class="notice">“Ectomorfo” pode ser uma autodescrição. O planejamento considera experiência, alimentação, recuperação e desempenho. Dor, lesões ou condições de saúde precisam de avaliação profissional.</div></section></div>`}
