function bindView(){for(const input of app.querySelectorAll('[data-live]'))input.oninput=()=>{const e=state.draft.data.exercises[Number(input.dataset.ex)],s=e.sets[Number(input.dataset.set)];s[input.dataset.live]=Number(input.value);changed()};
 const pf=app.querySelector('#people-form');if(pf)pf.onsubmit=async e=>{e.preventDefault();const q=new FormData(pf).get('q'),b=pf.querySelector('button');b.disabled=true;try{if(state.demo)throw new Error('A busca real será ativada após configurar Supabase.');const rows=await api('people?q='+encodeURIComponent(q));app.querySelector('#people-results').innerHTML=rows.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><br><small>@${esc(p.username)}</small></div>${button('Adicionar','add-friend','primary',`data-id="${p.id}"`)}</div>`).join('')||'<p class="empty">Nenhum usuário encontrado.</p>'}catch(err){toast(err.message)}finally{b.disabled=false}};
 const share=app.querySelector('#share-progress');if(share)share.onchange=async()=>{const next=share.checked;try{if(state.demo){state.profile.share_progress=next;demoPersist()}else state.profile=await api('profile','PATCH',{share_progress:next});toast(next?'Progresso visível para amigos aceitos.':'Progresso privado.')}catch(e){share.checked=!next;toast(e.message)}};
 const af=app.querySelector('#ai-form');if(af)af.onsubmit=async e=>{e.preventDefault();const b=af.querySelector('[type=submit]');b.disabled=true;b.textContent='Organizando sua resposta…';try{if(state.demo)throw new Error('Configure Gemini e Supabase para usar o auxiliar real.');const data=Object.fromEntries(new FormData(af));data.consent=data.consent==='on';data.photo_consent=data.photo_consent==='on';const signature=contextSignature();state.ai=await api('ai','POST',data);state.ai.signature=signature;await persistProposal();render()}catch(err){af.querySelector('[data-error]').textContent=err.message}finally{b.disabled=false;b.textContent='Enviar ao auxiliar'}};
}
function routineEditor(record=null,session=false,proposal=null){let data=clone(proposal||record?.data||{name:'',group:'A',exercises:[]});
 function editor(){formModal(session?'Editar esta sessão':record?'Editar ficha':'Criar ficha',field('name','Nome da ficha',data.name,'text','required maxlength="100"')+`<label>Grupo<select name="group">${['A','B','C','Outro'].map(x=>`<option ${data.group===x?'selected':''}>${x}</option>`).join('')}</select></label><div id="exercise-list">${data.exercises.map((e,i)=>`<div class="row"><div><strong>${esc(e.name)}</strong><br><small>${e.sets.length} séries · ${e.sets[0]?.reps||10} reps · ${e.rest||90}s descanso</small></div><div class="actions">${button('Editar','ex-edit','ghost',`data-index="${i}"`)}${button('↑','ex-up','ghost',`data-index="${i}" aria-label="Mover acima"`)}${button('✕','ex-delete','ghost danger',`data-index="${i}" aria-label="Remover exercício"`)}</div></div>`).join('')}</div>${button('Adicionar exercício','ex-add','ghost')}`,async f=>{data.name=f.name;data.group=f.group;if(!data.exercises.length)throw new Error('Adicione pelo menos um exercício.');if(session){state.draft.data={...state.draft.data,...data};changed();await saveDraft()}else await put('routine',data,record?.id,record?.version);toast('Ficha salva.');});
 const saveHeader=()=>{data.name=modal.querySelector('[name=name]').value;data.group=modal.querySelector('[name=group]').value};
 modal.querySelectorAll('[data-action^="ex-"]').forEach(b=>b.onclick=()=>{saveHeader();const i=Number(b.dataset.index);if(b.dataset.action==='ex-delete'){data.exercises.splice(i,1);editor()}else if(b.dataset.action==='ex-up'){if(i>0)[data.exercises[i-1],data.exercises[i]]=[data.exercises[i],data.exercises[i-1]];editor()}else exEditor(b.dataset.action==='ex-add'?null:i)});
 }
 function exEditor(i){const e=i===null?{name:'',purpose:'',execution:'',alternative:'',sets:[{kg:0,reps:10,done:false}],rest:90}:data.exercises[i];const library=starterRoutines().flatMap(r=>r.exercises);formModal('Exercício',`<label>Preencher a partir de um exemplo<select id="exercise-example"><option value="">Personalizado</option>${library.map((e,j)=>`<option value="${j}">${esc(e.name)}</option>`).join('')}</select></label>`+field('name','Nome',e.name,'text','required')+field('sets','Número de séries',e.sets.length,'number','required min="1" max="10"')+field('reps','Repetições por série',e.sets[0]?.reps||10,'number','required min="1" max="200"')+field('rest','Descanso (segundos)',e.rest||90,'number','required min="10" max="600"')+area('purpose','Para que serve',e.purpose)+area('execution','Como executar',e.execution)+field('alternative','Alternativa',e.alternative),async f=>{const n=Number(f.sets);if(n<1||n>10)throw new Error('Use de 1 a 10 séries.');const next={...e,id:e.id||uid(),name:f.name,purpose:f.purpose,execution:f.execution,alternative:f.alternative,rest:Number(f.rest),sets:Array.from({length:n},(_,j)=>e.sets[j]?{...e.sets[j],reps:Number(f.reps)!==Number(e.sets[0]?.reps)?Number(f.reps):e.sets[j].reps}:{kg:0,reps:Number(f.reps),done:false})};if(i===null)data.exercises.push(next);else data.exercises[i]=next;setTimeout(editor,0)},'Adicionar à ficha');modal.querySelector('#exercise-example').onchange=ev=>{if(ev.target.value==='')return;const x=library[Number(ev.target.value)];for(const k of ['name','purpose','execution','alternative','rest'])modal.querySelector(`[name=${k}]`).value=x[k];modal.querySelector('[name=sets]').value=x.sets.length;modal.querySelector('[name=reps]').value=x.sets[0].reps};}
 editor();}
function recordEditor(kind,r=null,proposal=null){const d=proposal||r?.data||{};let html;if(kind==='meal')html=field('name','Nome da refeição',d.name,'text','required')+field('time','Horário',d.time||'12:00','time','required')+area('content','Alimentos, porções e preparo',d.content)+area('purpose','Finalidade e observações',d.purpose);if(kind==='pantry')html=field('name','Alimento',d.name,'text','required')+field('quantity','Quantidade disponível ou planejada',d.quantity??1,'number','required min="0" step="0.01"')+field('unit','Unidade (g, kg, un)',d.unit||'un','text','required')+field('price','Preço estimado dessa quantidade (R$)',d.price||0,'number','min="0" step="0.01"')+`<label class="check"><input type="checkbox" name="available" ${d.available!==false?'checked':''}>Tenho em casa (desmarque se apenas pode comprar)</label>`;if(kind==='measurement')html=field('date','Data',d.date||new Date().toISOString().slice(0,10),'date','required')+field('weight','Peso (kg)',d.weight||latestWeight()||'','number','required min="1" max="499" step="0.1"')+[['waist','Cintura'],['belly','Barriga'],['chest','Peitoral'],['hip','Glúteo'],['neck','Pescoço'],['thigh','Coxa'],['relaxed_arm','Braço relaxado'],['arm','Braço contraído'],['forearm','Antebraço'],['calf','Panturrilha']].map(([k,l])=>field(k,l+' (cm)',d[k]||'','number','min="0" max="300" step="0.1"')).join('')+area('notes','Observações',d.notes);formModal(r?'Editar registro':`Novo registro: ${kind==='meal'?'refeição':kind==='pantry'?'alimento':'medidas'}`,html,async(f,form)=>{for(const k of ['weight','quantity','price','waist','belly','chest','hip','neck','thigh','relaxed_arm','arm','forearm','calf'])if(k in f)f[k]=f[k]===''?null:Number(f[k]);if(kind==='pantry')f.available=form.querySelector('[name=available]').checked;await put(kind,f,r?.id,r?.version);toast('Registro salvo.');if(kind==='measurement'||kind==='pantry')schedulePlan();});}
function profileEditor(){const p=state.profile,s=p.settings||{};const html=field('name','Seu nome',p.name,'text','required maxlength="80"')+field('username','Nome de usuário',p.username,'text','required pattern="[a-z0-9_]{3,24}"')+field('password','Senha atual (obrigatória se alterar nome ou usuário)','','password','autocomplete="current-password"')+field('age','Idade',s.age,'number','min="18" max="100"')+field('height','Altura (cm)',s.height,'number','min="100" max="250"')+field('weight','Peso de referência (kg)',s.weight,'number','min="1" max="499" step="0.1"')+field('target','Meta de peso (kg)',s.target,'number','min="1" max="499" step="0.1"')+field('goal','Objetivo e prioridades',s.goal)+`<label>Biotipo autodeclarado<select name="biotype">${['Não sei','Ectomorfo (autodeclarado)','Mesomorfo (autodeclarado)','Endomorfo (autodeclarado)','Prefiro não classificar'].map(x=>`<option ${s.biotype===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="subtle">Essa classificação não determina seu treino. O auxiliar ajuda a entender seu perfil, sem diagnosticar pelo corpo ou pelas fotos.</p><label>Experiência<select name="experience">${['Iniciante','Intermediário','Avançado'].map(x=>`<option ${s.experience===x?'selected':''}>${x}</option>`).join('')}</select></label>`+field('minutes','Quantos minutos você tem para cada treino?',s.minutes||60,'number','min="15" max="180"')+`<p class="subtle">Ex.: de 7h às 8h = 60 minutos. A IA ajusta exercícios, séries e descanso para caber nesse tempo.</p>`+field('days','Dias de treino por semana',s.days||3,'number','min="1" max="6"')+field('equipment','Equipamentos disponíveis',s.equipment)+area('limitations','Dores, lesões, condições de saúde e restrições alimentares',s.limitations)+field('sleep','Horas de sono habituais',s.sleep||'','number','min="0" max="16" step="0.5"')+area('schedule','Horários e rotina',s.schedule)+`<div class="notice">E-mail: ${esc(state.user.email)}. Fotos e medidas ficam privadas. Compartilhar progresso é opcional.</div><div class="actions">${button('Redefinir senha','change-password','ghost')}${button('Alterar e-mail','account-edit','ghost')}${button('Redefinir perfil','reset-profile','ghost')}${button('Excluir perfil e conta','delete-account','ghost danger')}</div>`;formModal('Meu perfil',html+`<label class="check"><input name="ai_auto" type="checkbox" ${s.ai_auto?'checked':''}>Gerar uma nova proposta de treino ao salvar mudanças no perfil, medidas ou TAF. Autorizo enviar esses dados ao Gemini. Fotos ficam excluídas.</label>`,async f=>{const previous=contextSignature();const settings={ai_auto:f.ai_auto==='on',...(s.music_url?{music_url:s.music_url}:{})};for(const k of ['age','height','weight','target','minutes','days','sleep'])settings[k]=f[k]===''?null:Number(f[k]);for(const k of ['goal','biotype','experience','equipment','limitations','schedule'])settings[k]=f[k];if(state.demo){state.profile={...p,name:f.name,username:f.username,settings};demoPersist()}else{const b={settings};if(f.name!==p.name)b.name=f.name;if(f.username!==p.username)b.username=f.username;if(b.name||b.username)b.password=f.password;state.profile=await api('profile','PATCH',b)}toast('Perfil atualizado.');if(previous!==contextSignature()||(!s.ai_auto&&settings.ai_auto))schedulePlan();});}
function speak(text){if(!('speechSynthesis'in window)){toast('Leitura em voz não disponível neste navegador.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='pt-BR';u.rate=1;speechSynthesis.speak(u)}
async function start(id){if(state.draft){state.route='workouts';render();return}const r=state.records.find(r=>r.id===id);if(!r)throw new Error('Ficha não encontrada.');const data=clone(r.data);const last=items('workout').filter(x=>x.data.name===data.name).sort((a,b)=>new Date(b.data.finished_at)-new Date(a.data.finished_at))[0];for(const e of data.exercises){const prev=last?.data.exercises.find(x=>x.id===e.id);for(let j=0;j<e.sets.length;j++){if(prev?.sets[j]){e.sets[j].kg=prev.sets[j].kg;e.sets[j].reps=prev.sets[j].reps;}e.sets[j].done=false;}}data.started_at=new Date().toISOString();data.log_id=uid();state.draft={id:uid(),kind:'draft',data};state.dirty=true;state.route='workouts';cacheDraft();render();await saveDraft()}
function updateTimes(){if(!state.draft)return;const now=Date.now(),elapsed=activeSeconds(state.draft.data,now);for(const e of document.querySelectorAll('[data-elapsed]'))e.textContent=duration(elapsed);const end=state.draft.data.rest_until,left=end?Math.max(0,Math.ceil((end-(state.draft.data.paused_at||now))/1000)):0;for(const e of document.querySelectorAll('[data-rest]'))e.textContent=end?(left?duration(left):'Pronto'):'—';}
function duration(s){return (Math.floor(s/60)).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0')}
setInterval(updateTimes,1000);
setInterval(async()=>{if(!state.user||state.demo||document.hidden||modal.open||state.route!=='friends'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{state.friends=await api('friends');state.stats=await api('stats');render()}catch{}},30000);
