 'toggle-password':b=>{const input=b.parentElement.querySelector('input');const visible=input.type==='password';input.type=visible?'text':'password';b.textContent=visible?'Ocultar':'Mostrar';b.setAttribute('aria-pressed',String(visible));b.setAttribute('aria-label',visible?'Ocultar senha':'Mostrar senha');},'pause-workout':()=>{togglePause(state.draft.data);changed();render();},'close':()=>modal.close(),'auth-login':()=>auth(),'auth-signup':()=>auth('signup'),'auth-recover':()=>auth('recover'),'demo':enterDemo,
 'nav':b=>{state.route=b.dataset.route;render()},'continue':()=>{state.route='workouts';render()},'start':b=>start(b.dataset.id),
 'profile':profileEditor,'new-routine':()=>routineEditor(),'edit-routine':b=>routineEditor(state.records.find(r=>r.id===b.dataset.id)),
 'new-meal':()=>recordEditor('meal'),'new-pantry':()=>recordEditor('pantry'),'new-measurement':()=>recordEditor('measurement'),
