 'upload-photo':()=>{if(state.demo)throw new Error('Envio de fotos precisa do Supabase.');formModal('Enviar foto privada',`<label>Foto (JPG, PNG ou WebP, até 8 MB)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label>${field('caption','Legenda','','text','maxlength="160"')}<p class="subtle">A imagem será reprocessada neste aparelho para retirar metadados antes do envio.</p>`,async(f,form)=>{const file=form.querySelector('[name=photo]').files[0];if(!file||file.size>8388608)throw new Error('Limite de 8 MB por foto.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw new Error('Não foi possível processar a imagem.');await api('photos?caption='+encodeURIComponent(f.caption),'POST',blob);state.photos=await api('photos');toast('Foto privada enviada.');},'Enviar');},
